selector_to_html = {"a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"FreeVortexTwist.html#pyskyfire.turbine.definition.FreeVortexTwist\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.definition.FreeVortexTwist\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine.definition.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FreeVortexTwist</span></span></dt><dd><p>Metal angles from hub to tip for a free-vortex row.</p><p>In a free vortex the axial velocity is the same at every radius and the\nswirl falls off as <code class=\"docutils literal notranslate\"><span class=\"pre\">1/r</span></code>, so <code class=\"docutils literal notranslate\"><span class=\"pre\">r*c_u</span></code> is constant across the span. A\nrotor\u2019s blade speed grows with <code class=\"docutils literal notranslate\"><span class=\"pre\">r</span></code>, so its relative angles twist more\nthan a stator\u2019s absolute ones.</p></dd>", "a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#functions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"BladeRow.html#pyskyfire.turbine.definition.BladeRow\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.definition.BladeRow\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine.definition.</span></span><span class=\"sig-name descname\"><span class=\"pre\">BladeRow</span></span></dt><dd><p>One row of blades, as hardware.</p></dd>", "a[href=\"#module-pyskyfire.turbine.definition\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.turbine.definition<a class=\"headerlink\" href=\"#module-pyskyfire.turbine.definition\" title=\"Link to this heading\">\u00b6</a></h1><p>The drawing of an axial turbine\u2019s bladed flow path.</p><p>A <a class=\"reference internal\" href=\"TurbineDefinition.html#pyskyfire.turbine.definition.TurbineDefinition\" title=\"pyskyfire.turbine.definition.TurbineDefinition\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">TurbineDefinition</span></code></a> is hardware and nothing else: an ordered tuple of\n<a class=\"reference internal\" href=\"BladeRow.html#pyskyfire.turbine.definition.BladeRow\" title=\"pyskyfire.turbine.definition.BladeRow\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">BladeRow</span></code></a> objects and the annular passage they sit in. It holds no\nvelocity triangles, no duty and no efficiency, so it does not care how it was\ndesigned. A meanline design produces one, a user can write one out by hand,\nand evaluators and the geometry builder read one.</p>", "a[href=\"TurbineDefinition.html#pyskyfire.turbine.definition.TurbineDefinition.build_geometry\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.definition.TurbineDefinition.build_geometry\">\n<span class=\"sig-name descname\"><span class=\"pre\">build_geometry</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">span_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">9</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chord_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">129</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Blade surfaces for every row, and each row\u2019s throat, measured from them.</p><p>Needs the optional <code class=\"docutils literal notranslate\"><span class=\"pre\">pyturbo-aero</span></code> package.</p></dd>", "a[href=\"TurbineDefinition.html#pyskyfire.turbine.definition.TurbineDefinition\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.definition.TurbineDefinition\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine.definition.</span></span><span class=\"sig-name descname\"><span class=\"pre\">TurbineDefinition</span></span></dt><dd><p>An axial turbine\u2019s rows and the annular passage through them.</p></dd>", "a[href=\"#pyskyfire.turbine.definition.metal_angles\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.definition.metal_angles\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine.definition.</span></span><span class=\"sig-name descname\"><span class=\"pre\">metal_angles</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">flow_in</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">flow_out</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">incidence</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">deviation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Metal angles for a row turning the flow from <code class=\"docutils literal notranslate\"><span class=\"pre\">flow_in</span></code> to <code class=\"docutils literal notranslate\"><span class=\"pre\">flow_out</span></code>.</p><p>Incidence is added to the inlet flow angle. Deviation is added to the\noutlet in the direction the row turns the flow, since the leaving flow\nfalls short of the metal and the blade has to turn it further.</p></dd>", "a[href=\"ThicknessDistribution.html#pyskyfire.turbine.definition.ThicknessDistribution\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.turbine.definition.ThicknessDistribution\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.turbine.definition.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ThicknessDistribution</span></span></dt><dd><p>How a section\u2019s thickness is laid along its camber line.</p><p>The section is drawn as offsets from the camber line: control points on\nthe suction side and on the pressure side, each a fraction of the row\u2019s\n<code class=\"docutils literal notranslate\"><span class=\"pre\">max_thickness</span></code>, spaced from leading edge towards trailing edge. The\nbuilt section\u2019s actual thickness is measured, not assumed from these.</p></dd>", "a[href=\"#conventions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Conventions<a class=\"headerlink\" href=\"#conventions\" title=\"Link to this heading\">\u00b6</a></h2><p>What is <em>not</em> here is anything the built section decides: the throat, and\nthe realised maximum thickness. <a class=\"reference internal\" href=\"TurbineDefinition.html#pyskyfire.turbine.definition.TurbineDefinition.build_geometry\" title=\"pyskyfire.turbine.definition.TurbineDefinition.build_geometry\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">TurbineDefinition.build_geometry()</span></code></a>\nmeasures those from the blades it builds.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
